// 麻将牌墩从东南角开始逆时针排列：
// - 南（下）：牌墩从右往左排列，空位在右边
// - 西（左）：牌墩从下往上排列，空位在下边（视觉上是右边）
// - 北（上）：牌墩从左往右排列，空位在左边
// - 东（右）：牌墩从上往下排列，空位在上边（视觉上是左边）
// 简化：North/East 空位在左边，South/West 空位在右边
const emptyOnLeft = (dir === 'North' || dir === 'East');

for (let i = 0; i < 17; i++) {
    const pile = document.createElement('div');
    pile.className = 'wall-pile';

    // 计算当前索引是否应该显示牌墩
    // emptyOnLeft: 剩余牌墩在右边，空位在左边 → 索引 >= (17 - pileCount) 显示牌
    // emptyOnRight: 剩余牌墩在左边，空位在右边 → 索引 < pileCount 显示牌
    const showTile = emptyOnLeft ? (i >= (17 - pileCount)) : (i < pileCount);

    if (showTile) {
        // 创建两层的牌 - 上层和下层
        const tile1 = document.createElement('div');
        tile1.className = 'wall-tile top-tile';
        const tile2 = document.createElement('div');
        tile2.className = 'wall-tile bottom-tile';

        // 计算当前牌墩在方位内的位置（从1开始，用于亮牌检测）
        // emptyOnLeft: 索引从 17-pileCount 开始对应第1墩
        // emptyOnRight: 索引从 0 开始对应第1墩
        const pilePosition = emptyOnLeft ? (i - (17 - pileCount) + 1) : (i + 1);

        // 检查是否是亮牌位置
        if (shownInfo && shownInfo.direction === seatNum && shownInfo.pile === pilePosition) {
            tile1.classList.add('shown');
            // 在亮牌位置显示麻将牌图片
            if (currentShownCard) {
                const imgSrc = getCardImageSrc(currentShownCard);
