    // 从抓牌方位开始，逆时针方向抓牌
    // 抓牌方位先抓完剩余的牌墩（17 - skipPiles）
    let remainingPilesToDraw = drawnPiles;

    // 首先处理抓牌方位
    // 抓牌方位可抓的牌墩 = 17 - skipPiles（跳过的部分保持满）
    const drawAvailablePiles = 17 - skipPiles;

    if (remainingPilesToDraw > 0) {
        if (remainingPilesToDraw >= drawAvailablePiles) {
            // 抓牌方位抓完，剩余为跳过的牌墩数
            wallState[drawDir] = skipPiles;
            remainingPilesToDraw -= drawAvailablePiles;
        } else {
            // 抓牌方位还剩一些
            wallState[drawDir] = skipPiles + (drawAvailablePiles - remainingPilesToDraw);
            remainingPilesToDraw = 0;
        }
    }

    // 然后逆时针处理其他方位
    let currentDirIdx = (drawIdx + 1) % 4;
    while (remainingPilesToDraw > 0 && currentDirIdx !== drawIdx) {
