        keptRange[drawDir] = { start: 1, count: skipPiles };
    }

    // 计算抓牌方位可抓的墩数
    let availableInDrawDir = 17 - skipPiles;

    if (remainingToDraw > 0) {
        if (remainingToDraw >= availableInDrawDir) {
            // 抓牌方位的可抓部分全部被抓
            keptRange[drawDir].count = skipPiles; // 保留的只是跳过的部分
            remainingToDraw -= availableInDrawDir;
        } else {
            // 只抓了一部分
            keptRange[drawDir].count = skipPiles + (availableInDrawDir - remainingToDraw);
            remainingToDraw = 0;
        }
    }

    // 逆时针处理其他方位
    let currentDirIdx = (drawIdx + 1) % 4;
    while (remainingToDraw > 0 && currentDirIdx !== drawIdx) {
        const currentDir = directionOrder[currentDirIdx];
        const currentPileOrder = pileOrder[currentDir];

        if (remainingToDraw >= 17) {
            // 这个方位全部被抓
            keptRange[currentDir] = { start: 0, count: 0 };
            remainingToDraw -= 17;
        } else {
            // 只抓了一部分
            // 保留的是序号 (remainingToDraw+1) 到 17（对于从大到小）
            // 或 1 到 (17-remainingToDraw)（对于从小到大）
            if (currentPileOrder.step === -1) {
                // 从大到小：保留序号1到(17-remainingToDraw)
                keptRange[currentDir] = { start: 1, count: 17 - remainingToDraw };
            } else {
                // 从小到大：保留序号(remainingToDraw+1)到17
                // 或者保留序号1到(17-remainingToDraw)？需要确认
                // 根据用户描述：南空了11-17，保留1-10 = 10墩
                // 如果 remainingToDraw=7，那么保留1-10 = 17-7=10
                keptRange[currentDir] = { start: 1, count: 17 - remainingToDraw };
            }
            remainingToDraw = 0;
        }
        currentDirIdx = (currentDirIdx + 1) % 4;
    }

    // 转换为前端需要的格式
    // wallState[direction] = { start: 起始序号, count: 保留数量 }
    this.gameState.wallState = {};
    for (let d = 1; d <= 4; d++) {
        const range = keptRange[d];
        this.gameState.wallState[d] = {
            start: range.count > 0 ? range.start : 0,
            count: range.count
        };
    }

    console.log(`牌墙状态更新: ${JSON.stringify(this.gameState.wallState)}`);
}

