// 更新牌墙状态
updateWallState() {
    // 计算已抓取的牌数（初始136张，减去亮牌1张，减去牌堆剩余）
    const initialCards = 136 - 1; // 总牌数减去亮牌
    const remainingCards = this.gameState.deck.length;
    const drawnCards = initialCards - remainingCards;

    // 牌墙初始状态：每个方位17墩
    const wallState = {
        1: { start: 1, count: 17 },  // 南
        2: { start: 1, count: 17 },  // 西
        3: { start: 17, count: 17 }, // 北
        4: { start: 17, count: 17 }  // 东
    };

    // 根据 drawInfo 确定抓牌起始位置
    const drawInfo = this.gameState.drawInfo;
    if (!drawInfo || !drawInfo.drawDirection) {
        this.gameState.wallState = wallState;
        return;
    }

    // 座位映射：1=南, 2=西, 3=北, 4=东
    // 逆时针顺序：南(1)→西(2)→北(3)→东(4)
    const directionOrder = [1, 2, 3, 4];
    const seatToDirection = { 1: '南', 2: '西', 3: '北', 4: '东' };

    // 牌墙序号方向（抓牌顺序在各方位内的方向）
    // 南：从1到17（step=1）
    // 西：从1到17（step=1）
    // 北：从17到1（step=-1）
    // 东：从17到1（step=-1）
    const pileStep = { 1: 1, 2: 1, 3: -1, 4: -1 };
    const pileStart = { 1: 1, 2: 1, 3: 17, 4: 17 };

    const drawDir = drawInfo.drawDirection;
    const drawIdx = directionOrder.indexOf(drawDir);
    const startPile = drawInfo.drawPile; // 抓牌起始墩序号

    // 计算已抓取的牌墩数（每墩2张）
    const drawnPiles = Math.floor(drawnCards / 2);

    console.log(`更新牌墙: 已抓${drawnCards}张=${drawnPiles}墩, 抓牌起始${seatToDirection[drawDir]}第${startPile}墩`);

    // 从抓牌起始位置开始，连续抓 drawnPiles 墩
    // 计算每个方位保留的牌墩

    let remainingToDraw = drawnPiles;
    let currentDirIdx = drawIdx;
    let currentPile = startPile;

    // 首先处理抓牌方位
    const step = pileStep[drawDir];
    let availableInDrawDir;

    if (step === 1) {
        // 南、西：序号从小到大
        // 从 startPile 开始到 17，共 (17 - startPile + 1) 墩可抓
        availableInDrawDir = 17 - startPile + 1;
    } else {
        // 北、东：序号从大到小
        // 从 startPile 开始到 1，共 startPile 墩可抓
        availableInDrawDir = startPile;
    }

    if (remainingToDraw >= availableInDrawDir) {
        // 抓牌方位的可抓部分全部被抓
        if (step === 1) {
            // 保留序号 1 到 (startPile - 1)
            wallState[drawDir] = { start: 1, count: startPile - 1 };
        } else {
            // 保留序号 (startPile + 1) 到 17
            wallState[drawDir] = { start: startPile + 1, count: 17 - startPile };
        }
        remainingToDraw -= availableInDrawDir;
        currentDirIdx = (currentDirIdx + 1) % 4;
    } else {
        // 只抓了一部分
        if (step === 1) {
            // 保留序号 1 到 (startPile - 1) 和 (startPile + remainingToDraw) 到 17
            const lastDrawn = startPile + remainingToDraw - 1;
            // 前面保留 1 到 (startPile-1)，后面保留 (lastDrawn+1) 到 17
            // 但这两部分不连续，需要特殊处理
            // 简化：只显示保留的部分，被抓的显示为空
            // 保留：序号 1 到 (startPile-1)，和序号 (lastDrawn+1) 到 17
            wallState[drawDir] = {
                start: 1,
                count: startPile - 1, // 前面保留的部分
                endKeep: { start: lastDrawn + 1, count: 17 - lastDrawn } // 后面保留的部分
            };
        } else {
            const lastDrawn = startPile - remainingToDraw + 1;
            wallState[drawDir] = {
                start: lastDrawn + 1,
                count: 17 - lastDrawn, // 前面保留的部分
                endKeep: { start: 17, count: startPile + 1 } // 后面保留的部分（如果有的话）
            };
        }
        remainingToDraw = 0;
    }

    // 逆时针处理其他方位
    while (remainingToDraw > 0 && currentDirIdx !== drawIdx) {
        const currentDir = directionOrder[currentDirIdx];
        const currentStep = pileStep[currentDir];

        if (remainingToDraw >= 17) {
            // 这个方位全部被抓
            wallState[currentDir] = { start: 0, count: 0 };
            remainingToDraw -= 17;
        } else {
            // 只抓了一部分
            if (currentStep === 1) {
                // 从序号1开始抓 remainingToDraw 墩
                // 保留序号 (remainingToDraw + 1) 到 17
                wallState[currentDir] = { start: remainingToDraw + 1, count: 17 - remainingToDraw };
            } else {
                // 从序号17开始抓 remainingToDraw 墩
                // 保留序号 1 到 (17 - remainingToDraw)
                wallState[currentDir] = { start: 1, count: 17 - remainingToDraw };
            }
            remainingToDraw = 0;
        }
        currentDirIdx = (currentDirIdx + 1) % 4;
    }

    this.gameState.wallState = wallState;
    console.log(`牌墙状态更新: ${JSON.stringify(wallState)}`);
}

